def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 45)
        return min(budget, 20)

    prev_bids = []
    pressured_opponents = 0
    rich_opponents = 0
    desperate_opponents = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) > budget:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opponents += 1

        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            if bid >= DAILY_SALARY * 0.75:
                pressured_opponents += 1

    high_supply = supply >= 21
    low_supply = supply <= 17

    if hp <= 2 or no_water_days >= 2:
        base_bid = 66
    elif hp <= 4 or no_water_days >= 1:
        base_bid = 52
    elif low_supply:
        base_bid = 46
    elif high_supply:
        base_bid = 28
    else:
        base_bid = 36

    if day >= 8:
        base_bid += 6
    if desperate_opponents >= 2:
        base_bid += 5
    if rich_opponents >= max(1, len(alive_opponents) // 2):
        base_bid += 4

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))

        if highest_prev >= 60:
            if hp > 4 and no_water_days == 0 and high_supply:
                base_bid = min(base_bid, 24)
            else:
                base_bid = max(base_bid, min(67, highest_prev + 2))
        elif highest_prev >= 45:
            base_bid = max(base_bid, min(58, avg_prev + 2))
        else:
            base_bid = max(base_bid, avg_prev + 1)

        if pressured_opponents == 0 and high_supply:
            base_bid = min(base_bid, 30)

    reserve = 0
    if hp > 4 and no_water_days == 0:
        reserve = 35
    elif hp > 2:
        reserve = 20

    affordable = max(0, budget - reserve)
    bid = min(base_bid, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(max(bid, 60), budget)
    elif no_water_days >= 1 and bid < 45:
        bid = min(45, budget)

    if bid < 0:
        bid = 0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((opp_id, opp))

    # Baseline: value water highly, but avoid reckless overspending.
    # We target a bid that would typically secure enough water for our requirement.
    # Since supply is shared, bidding around our requirement is reasonable.
    base_target = min(my_status['budget'], DAILY_SALARY * 0.55)

    # React to yesterday's observed bids.
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    # Compute a pressure signal.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        lowest_prev_bid = min(prev_bids)

        # If someone bid very aggressively yesterday, we match pressure but not fully.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If our hp is low, we must spend more.
            if my_status.get('hp', 0) <= 2:
                bid = min(my_status['budget'], DAILY_SALARY * 0.95)
            elif my_status.get('hp', 0) <= 3:
                bid = min(my_status['budget'], DAILY_SALARY * 0.75)
            else:
                bid = min(my_status['budget'], DAILY_SALARY * 0.65)
            return max(0.0, float(bid))

        # If bids were moderate, bid slightly above the median/low to secure water.
        if highest_prev_bid >= DAILY_SALARY * 0.55:
            # Use a small bump over the observed low to avoid getting outbid.
            bid = lowest_prev_bid + 5.0
            # Keep within budget and avoid extreme spending.
            bid = min(bid, my_status['budget'], DAILY_SALARY * 0.7)
            return max(0.0, float(bid))

        # If everyone was conservative yesterday, we can take water with a controlled bid.
        # Ensure we still stay meaningful relative to our need.
        bid = max(base_target, lowest_prev_bid + 2.0)
        bid = min(bid, my_status['budget'], DAILY_SALARY * 0.6)
        return max(0.0, float(bid))

    # No opponent trace bids available: decide based on our health and no-water days.
    hp = my_status.get('hp', 0)
    no_water_days = my_status.get('no_water_days', 0)

    # If we're near starvation, spend to avoid further no-water days.
    if hp <= 2 or no_water_days >= 2:
        return max(0.0, float(min(my_status['budget'], DAILY_SALARY * 0.9)))

    # Otherwise, bid moderately.
    return max(0.0, float(min(my_status['budget'], base_target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents left, bid minimally to secure water and save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.05) 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine competition level based on supply and number of active players
    supply = day_context['supply']
    num_possible_winners = int(supply // WATER_REQ)
    num_active_players = len(alive_opponents) + 1 # Myself + alive opponents

    # Scenario 1: Enough water for everyone (or more) - try to bid low
    if num_possible_winners >= num_active_players:
        if my_status['hp'] <= 3: # Still a bit cautious if HP is not great
            return min(my_status['budget'], DAILY_SALARY * 0.25)
        # Otherwise, bid very conservatively low
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Scenario 2: Water is scarce (num_possible_winners < num_active_players)
    # 1. My desperation takes priority
    if my_status['hp'] <= 2: # Critical HP
        return min(my_status['budget'], DAILY_SALARY * 0.95) # Bid very high to survive
    if my_status['hp'] <= 4: # Low HP
        return min(my_status['budget'], DAILY_SALARY * 0.75) # Bid high

    # 2. React to opponent's previous bids if water is scarce and I'm not critically desperate
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If previous bids were very high, opponents are aggressive
        if highest_prev_bid >= DAILY_SALARY * 0.8: 
            if my_status['hp'] > 5: # Good HP, try to win but don't overspend too much
                return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1))
            else: # My HP is okay, but not critical, still need water
                return min(my_status['budget'], DAILY_SALARY * 0.85) # Bid high

        # If previous bids were moderate, bid slightly above to win
        if highest_prev_bid >= DAILY_SALARY * 0.4:
            return min(my_status['budget'], highest_prev_bid + 1)

        # If previous bids were low, bid moderately to win
        return min(my_status['budget'], DAILY_SALARY * 0.45) 

    # Default bid if no previous bids (e.g., Day 1) and water is scarce, and I'm not desperate
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Check yesterday's highest bid from any alive opponent
    highest_prev_bid = None
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace')
            if prev and prev.get('bid') is not None:
                if highest_prev_bid is None or prev['bid'] > highest_prev_bid:
                    highest_prev_bid = prev['bid']

    if highest_prev_bid is not None:
        # React to opponent history
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
    else:
        # No opponent info: default strategy
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.8)
        else:
            bid = min(budget, DAILY_SALARY * 0.6)

    # Ensure bid is a float (as required by the game engine)
    return float(bid)
